-- =============================================================================
-- SIPAKAR RSUD KARDINAH: MIGRATION & POPULATE MASTER BARANG BMD
-- Sumber Data: Permendagri No. 108 Tahun 2016 (Tabel 2.6 Sub-Sub Rincian Objek)
-- Total Item: 13476 Barang Fisik (Level 7)
-- Target Engine: MySQL 8.0 / 8.4+
-- =============================================================================

SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;

-- 1. DDL: MEMASTIKAN TABEL DAN STRUKTUR KOLOM MASTER_BARANGS TERSEDIA
CREATE TABLE IF NOT EXISTS `master_barangs` (
  `id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `kode_barang` VARCHAR(100) NOT NULL UNIQUE COMMENT 'Kode identitas unik barang di SIPAKAR',
  `kode_permendagri` VARCHAR(50) DEFAULT NULL COMMENT 'Kodefikasi Level 7 Permendagri No. 108 Tahun 2016',
  `nama_barang` VARCHAR(255) NOT NULL COMMENT 'Nama/Uraian barang',
  `satuan` VARCHAR(50) DEFAULT 'Unit' COMMENT 'Satuan default pemesanan',
  `deskripsi` TEXT DEFAULT NULL COMMENT 'Kategori / spesifikasi hierarkis',
  `is_active` TINYINT(1) NOT NULL DEFAULT 1 COMMENT 'Status aktif',
  `created_by` BIGINT UNSIGNED DEFAULT NULL,
  `updated_by` BIGINT UNSIGNED DEFAULT NULL,
  `deleted_by` BIGINT UNSIGNED DEFAULT NULL,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` TIMESTAMP NULL DEFAULT NULL,
  INDEX `idx_master_barangs_kode_permendagri` (`kode_permendagri`),
  INDEX `idx_master_barangs_is_active` (`is_active`),
  FULLTEXT INDEX `ft_master_barangs_search` (`nama_barang`, `kode_barang`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Jika tabel master_barangs sudah ada dari migrasi lama, tambahkan kolom & index bila belum ada:
SET @col_exists = 0;
SELECT COUNT(*) INTO @col_exists FROM information_schema.columns 
WHERE table_schema = DATABASE() AND table_name = 'master_barangs' AND column_name = 'kode_permendagri';

SET @sql = IF(@col_exists = 0, 
    'ALTER TABLE `master_barangs` ADD COLUMN `kode_permendagri` VARCHAR(50) DEFAULT NULL AFTER `kode_barang`, ADD INDEX `idx_master_barangs_kode_permendagri` (`kode_permendagri`);', 
    'SELECT "Column kode_permendagri already exists" AS info;'
);
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

